package com.indiesoundquest.tournament.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="tournament_preference_report") public class TournamentPreferenceReport {
 @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="tournament_id",nullable=false) private Tournament tournament; @Enumerated(EnumType.STRING) @Column(nullable=false) private PreferenceReportStatus status; @Column(name="report_json",columnDefinition="json") private String reportJson; @Column(name="failure_message") private String failureMessage; @Column(name="version_number",nullable=false) private int versionNumber; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="generated_at") private Instant generatedAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected TournamentPreferenceReport(){} public static TournamentPreferenceReport pending(UUID id,Tournament tournament,int version){var r=new TournamentPreferenceReport();r.id=id;r.tournament=tournament;r.status=PreferenceReportStatus.PENDING;r.versionNumber=version;r.createdAt=Instant.now();r.updatedAt=r.createdAt;return r;} public void markRunning(){status=PreferenceReportStatus.RUNNING;updatedAt=Instant.now();} public void markReady(String json){status=PreferenceReportStatus.READY;reportJson=json;failureMessage=null;generatedAt=Instant.now();updatedAt=generatedAt;} public void markFailed(String message){status=PreferenceReportStatus.FAILED;failureMessage=message;updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getTournamentId(){return tournament.getId();} public PreferenceReportStatus getStatus(){return status;} public int getVersionNumber(){return versionNumber;} public String getReportJson(){return reportJson;} public String getFailureMessage(){return failureMessage;}
}
